def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    N = int(data[index])
    Q = int(data[index + 1])
    index += 2

    queries = []
    for _ in range(Q):
        if data[index] == '1':
            L = int(data[index + 1])
            R = int(data[index + 2])
            A = int(data[index + 3])
            B = int(data[index + 4])
            queries.append((1, L, R, A, B))
            index += 5
        elif data[index] == '2':
            L = int(data[index + 1])
            R = int(data[index + 2])
            queries.append((2, L, R))
            index += 3

    def calculate_stones(L, R, A, B):
        total_stones = 0
        for i in range(L, R + 1):
            total_stones += ((i - L + 1) * A) % B
        return total_stones

    def sum_in_range(L, R):
        total_stones = 0
        for query in queries:
            if query[0] == 1:
                L1, R1, A, B = query[1], query[2], query[3], query[4]
                if L1 <= R and L <= R1:
                    overlap_start = max(L, L1)
                    overlap_end = min(R, R1)
                    total_stones += calculate_stones(overlap_start, overlap_end, A, B)
        return total_stones

    results = []
    for query in queries:
        if query[0] == 2:
            L, R = query[1], query[2]
            result = sum_in_range(L, R)
            results.append(result)

    for result in results:
        print(result)

